def solve(tables: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    # Plan:
    # 1. Read raw CSV without header, filter out rows where first column is header marker or empty.
    # 2. For each valid match row, extract starting XI (positions 1-11) from columns 9-19.
    # 3. Extract substitutes bench (positions 12-18) from columns 31-37.
    # 4. Extract up to 3 substitution events from columns 21-29, convert to numeric, filter valid ones.
    # 5. For each match, compute per-player: in_squad (1 if in starting XI or bench), appearance (1 if starter or sub came on), minutes (90 for starters, reduced if subbed off; 0 for subs, increased if subbed on).
    # 6. Process substitutions chronologically: sort by minute, then input order; update minutes for off/on players.
    # 7. Aggregate across matches: sum in_squad, appearances, minutes; compute mins_per_game = minutes / appearances (or 0).
    # 8. Output sorted by In Squad desc, Player Name asc, with correct column order.

    df_raw = tables["input_01.csv"]
    # Ensure all columns are strings for consistency
    df_raw = df_raw.astype(str)

    # Filter rows: first column not empty and not a header marker
    header_markers = ["Match Details", "No.", "Liverpool Lineups"]
    df_matches = df_raw[
        df_raw.iloc[:, 0].str.strip().ne("") &
        ~df_raw.iloc[:, 0].str.strip().isin(header_markers)
    ].reset_index(drop=True)

    # Initialize accumulator
    records = []

    for _, row in df_matches.iterrows():
        # Starting XI: positions 1-11 from columns 9-19 (0-indexed: 8-18)
        starters = {}
        for col_idx in range(8, 19):
            pos = col_idx - 7  # 1-based position
            player = str(row.iloc[col_idx]).strip()
            if player and player.lower() != "nan":
                starters[pos] = player

        # Substitutes bench: positions 12-18 from columns 31-37 (0-indexed: 30-36)
        bench = {}
        for col_idx in range(30, 37):
            pos = col_idx - 18  # 12-based position, but we'll map to 12-18
            player = str(row.iloc[col_idx]).strip()
            if player and player.lower() != "nan":
                bench[pos] = player

        # Substitution events: columns 21-29 (0-indexed: 20-28)
        subs_raw = []
        # Sub1: cols 21,22,23 -> indices 20,21,22
        if not pd.isna(row.iloc[20]) and str(row.iloc[20]).strip() != "":
            try:
                sub_off = int(float(row.iloc[20]))
                sub_on = int(float(row.iloc[21]))
                sub_time = float(row.iloc[22])
                subs_raw.append((sub_off, sub_on, sub_time, 1))  # last is original order
            except (ValueError, TypeError):
                pass
        # Sub2: cols 24,25,26 -> indices 23,24,25
        if not pd.isna(row.iloc[23]) and str(row.iloc[23]).strip() != "":
            try:
                sub_off = int(float(row.iloc[23]))
                sub_on = int(float(row.iloc[24]))
                sub_time = float(row.iloc[25])
                subs_raw.append((sub_off, sub_on, sub_time, 2))
            except (ValueError, TypeError):
                pass
        # Sub3: cols 27,28,29 -> indices 26,27,28
        if not pd.isna(row.iloc[26]) and str(row.iloc[26]).strip() != "":
            try:
                sub_off = int(float(row.iloc[26]))
                sub_on = int(float(row.iloc[27]))
                sub_time = float(row.iloc[28])
                subs_raw.append((sub_off, sub_on, sub_time, 3))
            except (ValueError, TypeError):
                pass

        # Sort substitutions: first by minute asc, then by original order asc
        subs_sorted = sorted(subs_raw, key=lambda x: (x[2], x[3]))

        # Initialize per-match player stats
        player_stats = {}
        # Starters: in squad, appearance, minutes = 90 (may be reduced if subbed off)
        for pos, player in starters.items():
            player_stats[player] = {
                "in_squad": 1,
                "appearance": 1,
                "minutes": 90.0
            }
        # Bench: in squad, appearance = 0, minutes = 0 (may be increased if subbed on)
        for pos, player in bench.items():
            if player not in player_stats:
                player_stats[player] = {"in_squad": 1, "appearance": 0, "minutes": 0.0}
            else:
                # Player listed both as starter and bench? Should not happen, but ensure in_squad=1
                player_stats[player]["in_squad"] = 1

        # Track current on-field players: mapping position -> player
        # Initially, positions 1-11 are filled by starters
        position_to_player = {pos: player for pos, player in starters.items()}

        # Process substitutions in chronological order
        for sub_off_pos, sub_on_pos, sub_time, _ in subs_sorted:
            # Validate positions
            if sub_off_pos not in position_to_player:
                # Player to sub off is not on field (maybe already subbed off earlier)
                continue
            if sub_on_pos not in bench:
                # Player to sub on is not in bench
                continue

            off_player = position_to_player[sub_off_pos]
            on_player = bench[sub_on_pos]

            # Update minutes for off player: plays until sub_time
            player_stats[off_player]["minutes"] = sub_time

            # Update on player: appearance = 1, minutes = max(0, 90 - sub_time)
            if on_player not in player_stats:
                # Should not happen because bench players are already added
                player_stats[on_player] = {"in_squad": 1, "appearance": 0, "minutes": 0.0}
            player_stats[on_player]["appearance"] = 1
            player_stats[on_player]["minutes"] = max(0.0, 90.0 - sub_time)

            # Update on-field mapping: replace position with new player
            position_to_player[sub_off_pos] = on_player

        # Append records for this match
        for player, stats in player_stats.items():
            records.append({
                "Player Name": player,
                "In Squad": stats["in_squad"],
                "Appearances": stats["appearance"],
                "Mins Played": stats["minutes"]
            })

    # Aggregate across matches
    df_all = pd.DataFrame(records)
    if df_all.empty:
        # Return empty DataFrame with correct columns
        df_result = pd.DataFrame(columns=["In Squad", "Player Name", "Mins Played", "Appearances", "Mins per Game"])
    else:
        df_agg = df_all.groupby("Player Name", as_index=False).agg({
            "In Squad": "sum",
            "Appearances": "sum",
            "Mins Played": "sum"
        })
        # Compute Mins per Game
        df_agg["Mins per Game"] = df_agg.apply(
            lambda row: row["Mins Played"] / row["Appearances"] if row["Appearances"] > 0 else 0.0,
            axis=1
        )
        # Sort: In Squad desc, Player Name asc
        df_agg = df_agg.sort_values(by=["In Squad", "Player Name"], ascending=[False, True])
        # Reorder columns
        df_result = df_agg[["In Squad", "Player Name", "Mins Played", "Appearances", "Mins per Game"]]

    return {"output_01.csv": df_result}

