def solve(tables: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    # Plan:
    # - Sort input files alphabetically to assign years 2018-2022 sequentially
    # - Parse Sales/Profits: remove commas, handle K/M suffixes via multiplier, convert to integers
    # - Sum parsed values per input file to get yearly totals
    # - Construct output with Year, Sales, Profits in correct order
    # - Assuming input filenames are sorted as input_01.csv → 2018, input_02.csv → 2019, etc.

    def parse_value(s):
        if pd.isna(s) or s is None:
            return 0
        s = s.replace(',', '')
        if s.lower().endswith('k'):
            multiplier = 1000
            s = s[:-1]
        elif s.lower().endswith('m'):
            multiplier = 1000000
            s = s[:-1]
        else:
            multiplier = 1
        try:
            num = float(s)
        except:
            num = 0.0
        return int(round(num * multiplier))

    input_files = sorted([f for f in tables if f.startswith('input_')])
    yearly_data = []

    for i, fname in enumerate(input_files):
        df = tables[fname]
        sales_parsed = df['Sales'].apply(parse_value)
        profits_parsed = df['Profits'].apply(parse_value)
        yearly_data.append({
            'Year': 2018 + i,
            'Sales': sales_parsed.sum(),
            'Profits': profits_parsed.sum()
        })

    output_df = pd.DataFrame(yearly_data)[['Year', 'Sales', 'Profits']]
    return {'output_01.csv': output_df}

