def solve(tables: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    """
    Plan:
    - Process input_01.csv (two columns, no header) by replacing newlines with '||' per cell for consistent parsing.
    - Track current_matchday statefully: scan each row for "Matchday X of 38" (case-insensitive) and update for subsequent matches.
    - Parse match blocks: extract date (first token matching "DD MMM YY" -> convert to DD/MM/YYYY), home score (first integer after date skipping time patterns), home team (next non-noise token with immediate duplicate), away score/team similarly.
    - Assign source row number: increment counter only for rows with valid matches; first match-containing row gets 1.
    - Output matches with columns ordered: Away Score, Away Team, Home Score, Home Team, Matchday, Source Row Number, Date.
    Assumptions: 
    - First row with matches gets source row number 1 (skip announcer-only first row).
    - Team names identified by consecutive duplicate tokens after skipping noise tokens (e.g., 'FT', punctuation).
    - Two-digit years converted to 20xx (e.g., 23 -> 2023).
    """
    def parse_match_block(text: str, current_matchday: int | None) -> dict | None:
        if current_matchday is None:
            return None
        tokens = [t.strip() for t in text.split('||') if t.strip() != '']
        noise_set = {'FT', 'HT', 'Full', 'Time', 'Recap', 'Match', 'duration', 'minutes', 'seconds', 'of', 'Matchday', 'and', 'a', 'the', 'in', 'on', 'at', 'vs', '–', '-', 'vs.', 'vs', '(', ')', '[', ']', '{', '}', ',', '.', ';', ':'}
        months = {'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6, 'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12}

        # Extract date
        date_str, date_idx = None, -1
        for i, token in enumerate(tokens):
            match = re.match(r'(\d{1,2})\s*([A-Za-z]{3,})\s*(\d{2,4})', token)
            if not match:
                continue
            day, month_str, year_str = int(match.group(1)), match.group(2).title()[:3], match.group(3)
            month = months.get(month_str, months.get(month_str.lower(), None))
            if month is None:
                continue
            year_val = int(year_str)
            if len(year_str) == 2:
                year_val = 2000 + year_val
            date_str = f"{day:02d}/{month:02d}/{year_val}"
            date_idx = i
            break
        if date_str is None:
            return None

        # Extract home score
        home_score, home_score_idx = None, -1
        for i in range(date_idx + 1, len(tokens)):
            token = tokens[i]
            if re.match(r'\d+:\d+', token) or re.match(r'\d+\'', token):
                continue
            if token.isdigit():
                home_score = int(token)
                home_score_idx = i
                break
        if home_score is None:
            return None

        # Extract home team
        home_team, home_team_idx = None, -1
        i = home_score_idx + 1
        while i < len(tokens) - 1:
            if tokens[i] in noise_set:
                i += 1
                continue
            if tokens[i] == tokens[i + 1]:
                home_team = tokens[i]
                home_team_idx = i
                break
            i += 1
        if home_team is None:
            return None

        # Extract away score
        away_score, away_score_idx = None, -1
        for i in range(home_team_idx + 2, len(tokens)):
            token = tokens[i]
            if re.match(r'\d+:\d+', token) or re.match(r'\d+\'', token):
                continue
            if token.isdigit():
                away_score = int(token)
                away_score_idx = i
                break
        if away_score is None:
            return None

        # Extract away team
        away_team = None
        i = away_score_idx + 1
        while i < len(tokens) - 1:
            if tokens[i] in noise_set:
                i += 1
                continue
            if tokens[i] == tokens[i + 1]:
                away_team = tokens[i]
                break
            i += 1
        if away_team is None:
            return None

        return {
            'Date': date_str,
            'Home Team': home_team,
            'Home Score': home_score,
            'Away Team': away_team,
            'Away Score': away_score,
            'Matchday': current_matchday
        }

    df = tables['input_01.csv']
    current_matchday = None
    source_row_counter = 0
    output_rows = []

    for i, row in df.iterrows():
        # Update matchday from row
        for col in [0, 1]:
            text = str(row[col]) if not pd.isna(row[col]) else ""
            if text.strip() == "":
                continue
            match = re.search(r'Matchday\s+(\d+)\s*of\s*38[,.]?', text, re.IGNORECASE)
            if match:
                current_matchday = int(match.group(1))

        # Parse matches from both columns
        matches_in_row = []
        for col in [0, 1]:
            text = str(row[col]) if not pd.isna(row[col]) else ""
            if text.strip() == "":
                continue
            text_clean = text.replace('\n', '||')
            match_data = parse_match_block(text_clean, current_matchday)
            if match_data is not None:
                matches_in_row.append(match_data)

        # Assign source row number if matches found
        if matches_in_row:
            row_number = source_row_counter + 1
            for match in matches_in_row:
                match['Source Row Number'] = row_number
            output_rows.extend(matches_in_row)
            source_row_counter = row_number

    # Create output DataFrame with correct column order
    if output_rows:
        output_df = pd.DataFrame(output_rows)
        output_df = output_df[[
            'Away Score', 'Away Team', 'Home Score', 'Home Team', 
            'Matchday', 'Source Row Number', 'Date'
        ]]
    else:
        output_df = pd.DataFrame(columns=[
            'Away Score', 'Away Team', 'Home Score', 'Home Team', 
            'Matchday', 'Source Row Number', 'Date'
        ])

    return {'output_01.csv': output_df}

